def mark_citizen_returns(apps, schema_editor):
    """Documents a citizen sent back were left 'in_progress' at their final office, with no way to finish them."""
    Document = apps.get_model('documents', 'Document')
    DocumentLog = apps.get_model('documents', 'DocumentLog')
